#!/usr/bin/env python3
# luxarch:context-watch hook v3 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""At 85% context, tell the owner and the agent once: finish the step, run /wrap-up, before auto-compact.

The owner asked for time to run a wrap-up before the context fills. No hook fires at a context
threshold, and none is told the context size, so this reads the percentage the status line recorded
for THIS session (`statusline.py`: `~/.claude/context-watch/<session_id>.json`). With no record it is
silent: it never guesses the window size (200K or 1M) from a transcript.

PostToolUse, every tool. It fires once per session: a `systemMessage` the owner sees, and
`additionalContext` the agent reads (a hook cannot invoke a skill, so this asks; it does not call).
It re-arms when usage falls below 60% (after a compaction), so a long session is warned again before
its next one. Never blocks, never errors out. Python 3.9, stdlib only.
"""

from __future__ import annotations

import contextlib
import json
import os
import sys
from pathlib import Path

STATE_DIR = Path.home() / ".claude" / "context-watch"
THRESHOLD = 85.0
REARM_BELOW = 60.0

_AGENT = (
    "Context is {used:.0f}% full; auto-compaction is near. Finish the step you are on, then run "
    "/wrap-up now: commit, close or update the LuxPM issues, and persist every decision to LuxPM, so "
    "nothing is lost when the context is compacted."
)
_OWNER = (
    "Context {used:.0f}% full: the agent was asked to finish its step and run /wrap-up."
)

# named tuples, not `except (A, B):`: the 3.14 formatter rewrites that to `except A, B:`, which
# Python 3.9 (macOS, iOS repos) cannot parse
_UNREADABLE = (OSError, ValueError, KeyError, TypeError)
_BAD_INPUT = (ValueError, OSError, RecursionError)


def decide(
    event: dict[str, object], state_dir: Path = STATE_DIR
) -> dict[str, object] | None:
    session = str(event.get("session_id") or "")
    if not session or "/" in session or session.startswith("."):
        return None
    try:
        record = json.loads((state_dir / f"{session}.json").read_text(encoding="utf-8"))
        used = float(record["used_percentage"])
    except _UNREADABLE:
        return None
    marker = state_dir / f"{session}.warned"
    if used < REARM_BELOW:
        with contextlib.suppress(OSError):
            marker.unlink()
        return None
    if used < THRESHOLD:
        return None
    # v2: created exclusively, and only its creator warns. A check-then-write let parallel tool calls
    # both see no marker and both warn (2 in 30 trials with 6 concurrent hooks).
    try:
        fd = os.open(marker, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o644)
    except OSError:
        return (
            None  # already warned, or cannot remember it warned: stay silent either way
        )
    with contextlib.suppress(OSError):
        os.write(fd, f"{used}\n".encode())
    os.close(fd)
    return {
        "systemMessage": _OWNER.format(used=used),
        "hookSpecificOutput": {
            "hookEventName": "PostToolUse",
            "additionalContext": _AGENT.format(used=used),
        },
    }


def main() -> int:
    try:
        event = json.load(sys.stdin)
        out = decide(event if isinstance(event, dict) else {})
        if out is not None:
            sys.stdout.write(json.dumps(out) + "\n")
    except _BAD_INPUT:
        pass
    return 0


if __name__ == "__main__":
    sys.exit(main())
